public static void Main(Args _args)
{
    AIBBookInventoryUpdationController controller = AIBBookInventoryUpdationController::Construct();

    controller.initFromBookFormIfNeeded(_args);

    if(controller.prompt())
    {
        controller.runOperation();
    }
}

public void new(IdentifierName _className = '', IdentifierName _methodName = '', SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    super(_className, _methodName, _executionMode);
}

public void initFromBookFormIfNeeded(Args _args)
{
    FormRun callerFormRun = _args.caller();

    if(callerFormRun && callerFormRun.name() == formStr(AIBBook))
    {
        AIBBookTable bookActiveRecord = callerFormRun.dataSource(FormDataSourceStr(AIBBook, AIBBookTable)).cursor();

        AIBBookInventoryUpdationDataContract contract = this.getDataContract();

        contract.parmBookId(bookActiveRecord.Id);
    }
}

public static AIBBookInventoryUpdationController Construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    AIBBookInventoryUpdationController controller = new AIBBookInventoryUpdationController(classStr(AIBBookInventoryUpdationService), methodStr(AIBBookInventoryUpdationService, runProcess), _executionMode);

    controller.parmDialogCaption("@ITFormacion:UpdateBookInventory");

    return controller;
}

public boolean validateParameters()
{
    boolean ret;

    ret = super();

    if(ret)
    {
        AIBBookInventoryUpdationDataContract dataContract = this.getDataContract();
        ret = this.validateBook(dataContract.parmBookId()) 
                && this.validateNewQty(dataContract.parmNewQty());
    }

    return ret;
}

public boolean validateBook(AIBId _bookId)
{
    if(!AIBBookTable::exist(_bookId))
    {
        return checkFailed(strFmt("@ITFormacion:Book1DoesNotExists", _bookId));
    }
    return true;
}

public boolean validateNewQty(Qty _newQty)
{
    if(_newQty < 0)
    {
        return checkFailed("@ITFormacion:TransactionWouldMakeTheTotalNegative");
    }
    return true;
}
